INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-72d5-76d7-965d-a7ec40f395ee', 'bonnet-cotele-brode', 'Bonnet côtelé brodé', NULL, 'Maille côtelée double épaisseur, revers cousu. Série saisonnière, brodée en petit format sur le revers.', '01a0c9df-71f7-779b-b20c-130a1246c5d1', 'ACTIVE', 2800, NULL, 'DZD', 'TRACK', 'Acrylique doux, maille côtelée', 'Lavage à la main, séchage à plat', 'Broderie sur le revers, petit format.', false, false, false, false, NULL, NULL, 0, NULL, NULL, NULL, '2026-01-01 00:00:00+01', '2026-09-22 16:07:39.476+01', '2026-09-22 16:07:39.476+01', NULL, '{"en": {"name": "Embroidered ribbed beanie"}}') ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-72e8-7582-b04e-79a44103463a', 'echantillon-interne-non-publie', 'Échantillon interne (non publié)', NULL, 'Produit en brouillon utilisé par les tests de visibilité. Ne doit jamais apparaître dans la boutique.', '01a0c9df-71f3-776d-831a-9c6e98120d6c', 'DRAFT', 1000, NULL, 'DZD', 'DONT_TRACK', NULL, NULL, NULL, false, false, false, false, NULL, NULL, 0, NULL, NULL, NULL, NULL, '2026-09-22 16:07:39.495+01', '2026-09-22 16:07:39.495+01', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-71fe-7c53-8fd4-33ff0f2f765b', 't-shirt-brode-classique', 'T-shirt brodé classique', 'Coupe droite, broderie poitrine', 'Coton peigné 180 g/m² à la maille serrée, coupe droite, col côtelé renforcé par une bande de propreté. La broderie est réalisée après montage, sur la pièce finie, ce qui permet de la placer précisément.', '01a0c9df-71f3-776d-831a-9c6e98120d6c', 'ACTIVE', 4800, 6000, 'DZD', 'TRACK', '100 % coton peigné, 180 g/m²', 'Lavage 30°, sur l’envers, sans sèche-linge', 'Broderie poitrine gauche, fil polyester haute ténacité, jusqu’à 3 couleurs.', true, true, false, true, '01a0c9df-7309-7d16-9ceb-c25e148b0742', NULL, 0, NULL, NULL, NULL, '2026-01-02 00:00:00+01', '2026-09-22 16:07:39.261+01', '2026-09-22 16:07:39.545+01', NULL, '{"en": {"name": "Classic embroidered t-shirt", "material": "100% combed cotton, 180 gsm", "subtitle": "Straight cut, chest embroidery", "description": "Tightly knitted 180 gsm combed cotton, straight cut, ribbed collar reinforced with a taped seam. The embroidery is worked after making up, on the finished garment, which is what lets it be placed precisely.", "careInstructions": "Wash at 30°, inside out, do not tumble dry", "embroideryDetails": "Left chest embroidery, high-tenacity polyester thread, up to 3 colours."}}') ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-7264-739b-896d-3921080140d6', 'sweat-capuche-brode', 'Sweat à capuche brodé', 'Molleton 320 g/m²', 'Molleton gratté 320 g/m², capuche doublée en jersey, poche kangourou et bord-côtes élasthanne aux poignets. La pièce la plus demandée pour les commandes en série.', '01a0c9df-71f5-7452-b6f0-199d1510349a', 'ACTIVE', 9200, NULL, 'DZD', 'TRACK', '80 % coton, 20 % polyester, 320 g/m²', 'Lavage 30°, sur l’envers, sans sèche-linge', 'Broderie poitrine ou dos, jusqu’à 15 cm de large.', true, false, false, true, '01a0c9df-7309-7d16-9ceb-c25e148b0742', NULL, 0, NULL, NULL, NULL, '2026-01-02 00:00:00+01', '2026-09-22 16:07:39.363+01', '2026-09-22 16:07:39.545+01', NULL, '{"en": {"name": "Embroidered hooded sweatshirt", "material": "80% cotton, 20% polyester, 320 gsm", "subtitle": "320 gsm fleece", "description": "Brushed 320 gsm fleece, jersey-lined hood, kangaroo pocket and elastane ribbing at the cuffs. The piece most often asked for in batches.", "careInstructions": "Wash at 30°, inside out, do not tumble dry", "embroideryDetails": "Chest or back embroidery, up to 15 cm wide."}}') ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-72e0-7647-a287-feaace4ab990', 'tablier-atelier-brode', 'Tablier d’atelier brodé', NULL, 'Toile de coton épaisse, bavette haute, sangles croisées dans le dos et double poche ventrale. Brodé au nom de l’artisan ou de l’établissement.', '01a0c9df-71f7-779b-b20c-130a1246c5d1', 'ACTIVE', 5400, NULL, 'DZD', 'MADE_TO_ORDER', '100 % coton, 280 g/m²', 'Lavage 40°', 'Broderie bavette, texte ou logo jusqu’à 12 cm.', false, false, false, true, '01a0c9df-7309-7d16-9ceb-c25e148b0742', NULL, 0, NULL, NULL, NULL, '2026-01-01 00:00:00+01', '2026-09-22 16:07:39.487+01', '2026-09-22 16:07:39.545+01', NULL, '{"en": {"name": "Embroidered workshop apron"}}') ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-7297-78a4-b724-1eba3c912595', 'polo-pique-brode', 'Polo piqué brodé', NULL, 'Piqué de coton 220 g/m², col et bord-côte tricotés, patte trois boutons nacrés. Le vêtement des commandes d’entreprise, où la broderie remplace le logo imprimé.', '01a0c9df-71f6-7792-84fc-31bed8eba9e7', 'ACTIVE', 6400, NULL, 'DZD', 'TRACK', '100 % coton piqué, 220 g/m²', 'Lavage 30°, repassage doux', 'Broderie poitrine gauche, logo jusqu’à 8 cm.', false, false, false, true, '01a0c9df-7309-7d16-9ceb-c25e148b0742', NULL, 0, NULL, NULL, NULL, '2026-01-01 00:00:00+01', '2026-09-22 16:07:39.414+01', '2026-09-22 16:07:39.545+01', NULL, '{"en": {"name": "Embroidered piqué polo", "material": "100% piqué cotton, 220 gsm", "description": "220 gsm cotton piqué, knitted collar and cuffs, three-button placket in mother-of-pearl. The garment of company orders, where embroidery replaces a printed logo.", "careInstructions": "Wash at 30°, warm iron", "embroideryDetails": "Left chest embroidery, logo up to 8 cm."}}') ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-72bc-7058-bfee-ede267dab0d4', 'casquette-brodee', 'Casquette brodée', NULL, 'Casquette six panneaux, visière préformée, fermeture métal réglable. Taille unique, brodée sur le panneau frontal.', '01a0c9df-71f7-779b-b20c-130a1246c5d1', 'ACTIVE', 3200, NULL, 'DZD', 'TRACK', 'Sergé de coton', 'Nettoyage à la main', 'Broderie frontale, 5 cm de haut maximum.', false, false, true, true, '01a0c9df-7309-7d16-9ceb-c25e148b0742', NULL, 0, NULL, NULL, NULL, '2026-01-01 00:00:00+01', '2026-09-22 16:07:39.45+01', '2026-09-22 16:07:39.545+01', NULL, '{"en": {"name": "Embroidered cap", "material": "Cotton twill", "description": "Six-panel cap, pre-curved peak, adjustable metal fastening. One size, embroidered on the front panel.", "careInstructions": "Clean by hand", "embroideryDetails": "Front embroidery, 5 cm high at most."}}') ON CONFLICT DO NOTHING;
INSERT INTO public.products (id, slug, name, subtitle, description, category_id, status, base_price, compare_at_price, currency, stock_policy, material, care_instructions, embroidery_details, is_featured, is_best_seller, is_new_arrival, is_customizable, customization_profile_id, rating_average, rating_count, seo_title, seo_description, og_image_key, published_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-72cd-76fb-b8b7-ce32eb4f277b', 'tote-bag-toile-epaisse', 'Tote bag toile épaisse', NULL, 'Toile de coton 340 g/m², anses renforcées de 70 cm, coutures doublées aux points de tension. Se brode particulièrement bien en monogramme.', '01a0c9df-71f7-779b-b20c-130a1246c5d1', 'ACTIVE', 2500, NULL, 'DZD', 'MADE_TO_ORDER', '100 % coton, 340 g/m²', 'Lavage 30°', 'Monogramme ou logo, centré, jusqu’à 20 cm.', false, false, false, true, '01a0c9df-7309-7d16-9ceb-c25e148b0742', NULL, 0, NULL, NULL, NULL, '2026-01-01 00:00:00+01', '2026-09-22 16:07:39.468+01', '2026-09-22 16:07:39.545+01', NULL, '{"en": {"name": "Heavy canvas tote bag", "material": "100% cotton, 340 gsm", "description": "340 gsm cotton canvas, reinforced 70 cm handles, seams doubled at the stress points. Takes a monogram particularly well.", "careInstructions": "Wash at 30°", "embroideryDetails": "Monogram or logo, centred, up to 20 cm."}}') ON CONFLICT DO NOTHING;


