INSERT INTO public.gallery_items (id, slug, title, description, image_key, thumbnail_key, alt, product_type, embroidery_type, "position", is_featured, is_published, source_order_id, source_design_file_id, customer_consent_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-7330-7937-a207-9a206d48daf0', 'logo-cabinet-architecture-polo', 'Logo d’un cabinet d’architecture', 'Logo deux couleurs brodé en poitrine gauche sur une série de polos piqué. Le trait fin a été redessiné avant numérisation pour tenir à cette taille.', 'gallery/logo-cabinet-architecture-polo.jpg', NULL, 'Polo bleu nuit avec un logo brodé blanc en poitrine gauche', 'Polo', 'Logo d’entreprise', 1, true, true, NULL, NULL, NULL, '2026-09-22 16:07:39.567+01', '2026-09-22 16:07:39.567+01', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.gallery_items (id, slug, title, description, image_key, thumbnail_key, alt, product_type, embroidery_type, "position", is_featured, is_published, source_order_id, source_design_file_id, customer_consent_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-7336-7f3d-ad48-14d38978cede', 'prenoms-sweats-equipe', 'Prénoms sur une série de sweats', 'Vingt sweats à capuche, un prénom brodé par pièce sous la nuque. Chaque pièce est passée séparément sur la machine.', 'gallery/prenoms-sweats-equipe.jpg', NULL, 'Sweat gris avec un prénom brodé en fil écru sous la nuque', 'Sweat', 'Prénom', 2, true, true, NULL, NULL, NULL, '2026-09-22 16:07:39.573+01', '2026-09-22 16:07:39.573+01', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.gallery_items (id, slug, title, description, image_key, thumbnail_key, alt, product_type, embroidery_type, "position", is_featured, is_published, source_order_id, source_design_file_id, customer_consent_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-7339-7302-bd86-9fcdd3803877', 'casquettes-club-sportif', 'Casquettes d’un club sportif', 'Écusson brodé en relief sur la face avant de casquettes six panneaux, en trois couleurs de fil.', 'gallery/casquettes-club-sportif.jpg', NULL, 'Casquette noire portant un écusson brodé en relief', 'Casquette', 'Écusson', 3, true, true, NULL, NULL, NULL, '2026-09-22 16:07:39.576+01', '2026-09-22 16:07:39.576+01', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.gallery_items (id, slug, title, description, image_key, thumbnail_key, alt, product_type, embroidery_type, "position", is_featured, is_published, source_order_id, source_design_file_id, customer_consent_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-733b-71e1-9072-446952e0a602', 'tote-bags-librairie', 'Tote bags pour une librairie', 'Motif au trait brodé sur toile épaisse, en un seul fil, sur cinquante sacs.', 'gallery/tote-bags-librairie.jpg', NULL, 'Tote bag en toile écrue avec un motif au trait brodé', 'Tote bag', 'Motif', 4, true, true, NULL, NULL, NULL, '2026-09-22 16:07:39.578+01', '2026-09-22 16:07:39.578+01', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.gallery_items (id, slug, title, description, image_key, thumbnail_key, alt, product_type, embroidery_type, "position", is_featured, is_published, source_order_id, source_design_file_id, customer_consent_at, created_at, updated_at, deleted_at, translations) VALUES ('01a0c9df-733d-7bf9-ab5a-c5dbfbb9a428', 'tabliers-restaurant', 'Tabliers d’un restaurant', 'Nom de l’établissement brodé sur la bavette, en fil ton sur ton, sur tablier coton lourd.', 'gallery/tabliers-restaurant.jpg', NULL, 'Tablier en coton lourd avec un nom brodé ton sur ton sur la bavette', 'Tablier', 'Texte', 5, false, true, NULL, NULL, NULL, '2026-09-22 16:07:39.58+01', '2026-09-22 16:07:39.58+01', NULL, NULL) ON CONFLICT DO NOTHING;
