INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7343-76c2-9c45-0bd89c90629b', 'BANNER', 1, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-22 16:07:39.586+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7345-733f-bb41-16a3ebde92b2', 'HERO', 2, true, 'Vos idées, brodées.', NULL, 'Envoyez un logo, un prénom ou un dessin : nous le brodons sur le vêtement de votre choix. Ou choisissez une pièce déjà brodée dans la boutique.', 'Créer ma broderie', '/custom', NULL, '{"en": {"body": "Send us a logo, a name or a drawing: we embroider it on the garment you choose. Or pick a piece we have already embroidered from the shop.", "note": "Quoted within 6 working hours · from a single piece", "title": "Your idea, embroidered.", "eyebrow": "Embroidery workshop · Algeria", "ctaLabel": "Start my embroidery", "secondaryCtaLabel": "See the shop"}, "note": "Devis sous 6 heures ouvrées · à partir d’une seule pièce", "eyebrow": "Atelier de broderie · Algérie", "imageAlt": "", "imageKey": "site/hero.jpg", "secondaryCtaHref": "/shop", "secondaryCtaLabel": "Voir la boutique"}', '2026-09-22 16:07:39.588+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7346-7f4f-8dcf-3685f33bb6b9', 'HOW_IT_WORKS', 3, true, 'Quatre étapes, et vous savez ce que ça coûte.', NULL, 'Pas de « contactez-nous pour un prix ». Le montant s’affiche pendant que vous configurez, et vous partez avec un chiffre.', NULL, NULL, NULL, '{"en": {"body": "No \"contact us for a price\". The amount appears while you configure, and you leave with a figure.", "title": "Four steps, and you know what it costs.", "points": [{"body": "T-shirt, sweatshirt, polo, cap or tote bag. One catalogue serves both the shop and the made-to-order side.", "icon": "shirt", "title": "Choose the garment"}, {"body": "Chest, back, sleeve or lapel. Each placement has its own size limits, shown on screen.", "icon": "ruler", "title": "Choose the placement"}, {"body": "A logo, a photo, a name or an idea in writing. Vector files give the best result.", "icon": "upload", "title": "Send your design"}, {"body": "An immediate price for simple configurations, a priced quote within 6 working hours for the rest.", "icon": "sparkles", "title": "Get the price"}], "eyebrow": "Made to order"}, "points": [{"body": "T-shirt, sweat, polo, casquette ou tote bag. Le même catalogue sert la boutique et le sur-mesure.", "icon": "shirt", "title": "Choisissez le vêtement"}, {"body": "Poitrine, dos, manche ou revers. Chaque emplacement a ses limites de taille, indiquées à l’écran.", "icon": "ruler", "title": "Choisissez l’emplacement"}, {"body": "Un logo, une photo, un prénom ou une idée écrite. Les formats vectoriels donnent le meilleur rendu.", "icon": "upload", "title": "Envoyez votre design"}, {"body": "Prix immédiat pour les configurations simples, devis chiffré sous 6 heures ouvrées pour les autres.", "icon": "sparkles", "title": "Recevez le prix"}], "eyebrow": "Sur mesure"}', '2026-09-22 16:07:39.589+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7348-787a-9f8a-c1defc5e84e3', 'CATEGORY_GRID', 4, false, 'Par type de pièce', NULL, NULL, 'Tout voir', '/shop', NULL, '{"en": {"title": "By kind of piece", "eyebrow": "The catalogue", "ctaLabel": "See everything"}, "limit": 4, "eyebrow": "Le catalogue"}', '2026-09-22 16:07:39.591+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-734a-71b8-b4df-1431efdc111a', 'FEATURED_PRODUCTS', 5, true, 'Pièces prêtes à porter', NULL, NULL, 'Tout voir', '/shop', NULL, '{"en": {"title": "Ready-to-wear pieces", "eyebrow": "The shop", "ctaLabel": "See everything"}, "limit": 4, "eyebrow": "La boutique"}', '2026-09-22 16:07:39.593+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-734b-7bb5-b16c-59891c4fe626', 'GALLERY', 6, true, 'Ce que nous avons brodé', NULL, 'Des pièces réalisées à l’atelier, pour des entreprises, des clubs et des familles.', 'Voir tout notre travail', '/gallery', NULL, '{"en": {"body": "Pieces made in the workshop, for companies, clubs and families.", "title": "What we have embroidered", "eyebrow": "Our work", "ctaLabel": "See all our work"}, "limit": 4, "eyebrow": "Notre travail"}', '2026-09-22 16:07:39.594+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-734d-7465-89e7-a8f7896d8f66', 'WHY_US', 7, true, 'Le fil fait la différence.', NULL, 'Chaque pièce est brodée sur machine industrielle après numérisation du motif — une étape que nous faisons nous-mêmes, parce qu’un fichier mal numérisé se voit sur le vêtement fini.', NULL, NULL, NULL, '{"en": {"body": "Every piece is embroidered on an industrial machine after the design has been digitised — a step we do ourselves, because a badly digitised file shows on the finished garment.", "title": "The thread is the difference.", "points": [{"body": "The thread goes through the fabric. Embroidery does not flake in the wash or crack under an iron, the way a print does.", "title": "Embroidered, not printed"}, {"body": "One cap for yourself, or fifty polos for a team. The quantity discount applies on its own.", "title": "From a single piece"}, {"body": "The builder shows an estimate at every step. No order leaves without the amount being accepted.", "title": "You see the price first"}], "eyebrow": "The workshop"}, "points": [{"body": "Le fil traverse le tissu. Une broderie ne s’écaille pas au lavage et ne se fissure pas au repassage, contrairement au flocage.", "title": "Brodé, pas imprimé"}, {"body": "Une seule casquette pour vous, ou cinquante polos pour une équipe. Le tarif dégressif s’applique automatiquement.", "title": "À partir d’une pièce"}, {"body": "Le configurateur affiche une estimation à chaque étape. Aucune commande ne part sans que le montant soit accepté.", "title": "Vous voyez le prix avant"}], "eyebrow": "L’atelier", "showDelivery": true}', '2026-09-22 16:07:39.596+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-734e-7a0d-a69b-ea1359e8db1f', 'REVIEWS', 8, true, 'Ce qu’en disent nos clients', NULL, NULL, NULL, NULL, NULL, '{"en": {"title": "What our customers say", "eyebrow": "Verified reviews"}, "limit": 3, "eyebrow": "Avis vérifiés"}', '2026-09-22 16:07:39.597+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7350-7077-bd29-ca9306201dac', 'CUSTOM_CTA', 9, true, 'Une commande pour votre équipe ?', NULL, 'Envoyez-nous votre logo et le nombre de pièces. Vous recevez un devis chiffré, ligne par ligne, sous 6 heures ouvrées.', 'Demander un devis', '/custom', NULL, '{"en": {"body": "Send us your logo and the number of pieces. You get a quote, priced line by line, within 6 working hours.", "title": "An order for your team?", "eyebrow": "Companies and clubs", "ctaLabel": "Ask for a quote"}, "eyebrow": "Entreprises et clubs"}', '2026-09-22 16:07:39.599+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7351-7506-bce5-8c46de1abf30', 'SOCIAL', 10, true, 'Nous suivre', NULL, NULL, NULL, NULL, NULL, '{"en": {"title": "Follow us", "eyebrow": "The workshop, day to day"}, "eyebrow": "L’atelier au quotidien"}', '2026-09-22 16:07:39.6+01') ON CONFLICT DO NOTHING;
INSERT INTO public.homepage_sections (id, type, "position", is_enabled, title, subtitle, body, cta_label, cta_href, image_key, config, updated_at) VALUES ('01a0c9df-7352-7e0e-9d34-058f05f9e0ce', 'FINAL_CTA', 11, true, 'Envoyez-nous votre idée.', NULL, 'Un logo d’entreprise, le prénom d’un enfant, un dessin fait à la main. Si cela tient sur du tissu, cela se brode.', 'Créer ma broderie', '/custom', NULL, '{"en": {"body": "A company logo, a child’s name, a drawing made by hand. If it fits on fabric, it can be embroidered.", "title": "Send us your idea.", "eyebrow": "Ready to start?", "ctaLabel": "Start my embroidery"}, "eyebrow": "Prêt à commencer ?"}', '2026-09-22 16:07:39.601+01') ON CONFLICT DO NOTHING;


