INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('brand.name', 'Bizeora', 'STRING', 'brand', 'Brand name', 'Temporary placeholder. Replacing it also means editing config/brand.ts.', false, '2026-09-22 16:07:39.226+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('brand.logoKey', '', 'STRING', 'brand', 'Logo asset key', 'Public bucket key. Empty falls back to the bundled asset in config/brand.ts.', false, '2026-09-22 16:07:39.227+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('contact.whatsapp', '', 'STRING', 'contact', 'WhatsApp number', 'E.164. Drives the floating contact button and quote follow-up links.', false, '2026-09-22 16:07:39.228+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('shipping.defaultFreeThreshold', '0', 'MONEY', 'shipping', 'Default free-delivery threshold', 'Creation default only. Never read at calculation time — shipping_rates.freeOverAmount is the sole runtime source (BUSINESS-RULES.md 4.2).', false, '2026-09-22 16:07:39.23+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.depositPercent', '5000', 'NUMBER', 'custom_orders', 'Deposit percentage', 'BASIS POINTS. 5000 = 50%. Never a fraction (ADR-018).', false, '2026-09-22 16:07:39.231+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.quoteValidityDays', '14', 'NUMBER', 'custom_orders', 'Quote validity (days)', 'How long an unanswered quote may be accepted (BUSINESS-RULES.md 7.4).', false, '2026-09-22 16:07:39.232+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.acceptanceValidityDays', '7', 'NUMBER', 'custom_orders', 'Acceptance validity (days)', 'How long an accepted quote stays checkout-valid (BUSINESS-RULES.md 7.10).', false, '2026-09-22 16:07:39.232+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.responseTimeHours', '6', 'NUMBER', 'custom_orders', 'Stated response time (working hours)', 'Shown to customers on the request confirmation screen.', false, '2026-09-22 16:07:39.233+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.quoteThresholdQuantity', '10', 'NUMBER', 'custom_orders', 'Fixed-price quantity threshold', 'Above this a configuration needs a quote (BUSINESS-RULES.md 2.3.5).', false, '2026-09-22 16:07:39.234+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.quoteThresholdThreadColors', '3', 'NUMBER', 'custom_orders', 'Fixed-price thread-colour threshold', 'Above this a configuration needs a quote (BUSINESS-RULES.md 2.3.4).', false, '2026-09-22 16:07:39.235+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.quoteThresholdInstructionLength', '200', 'NUMBER', 'custom_orders', 'Fixed-price instruction-length threshold', 'At or above this character count a configuration needs a quote (BUSINESS-RULES.md 2.3.6).', false, '2026-09-22 16:07:39.235+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.maxThreadColors', '8', 'NUMBER', 'custom_orders', 'Maximum selectable thread colours', 'Hard configuration limit (BUSINESS-RULES.md 9.6). Distinct from the quote threshold of 3.', false, '2026-09-22 16:07:39.236+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.estimateBandPercent', '1500', 'NUMBER', 'custom_orders', 'Estimate range band', 'BASIS POINTS. 1500 = 15% (BUSINESS-RULES.md 2.4.2).', false, '2026-09-22 16:07:39.237+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.threadColorSurchargePerColor', '150', 'MONEY', 'custom_orders', 'Thread colour surcharge, per colour beyond the first', 'PLACEHOLDER pending the owner. Minor units. The per-colour rate BUSINESS-RULES.md 2.2 reads from settings.', false, '2026-09-22 16:07:39.238+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.textSurcharge', '250', 'MONEY', 'custom_orders', 'Embroidered text surcharge, per unit', 'PLACEHOLDER pending the owner. Minor units. Applied once per unit when the configuration carries text (BUSINESS-RULES.md 2.2).', false, '2026-09-22 16:07:39.238+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.setupFee', '1200', 'MONEY', 'custom_orders', 'Digitising setup fee, per configuration', 'PLACEHOLDER pending the owner. Minor units. Charged ONCE per configuration, not per unit, and waived above the quantity below (BUSINESS-RULES.md 2.2).', false, '2026-09-22 16:07:39.239+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.setupFeeWaiverQuantity', '25', 'NUMBER', 'custom_orders', 'Setup fee waiver quantity', 'PLACEHOLDER pending the owner. At or above this quantity the setup fee is waived (BUSINESS-RULES.md 2.2).', false, '2026-09-22 16:07:39.24+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('custom_orders.depositWindowDays', '7', 'NUMBER', 'custom_orders', 'Deposit follow-up window (days)', 'PLACEHOLDER pending the owner. After this an unpaid deposit order is flagged for follow-up; it is never auto-cancelled (BUSINESS-RULES.md 8.10.5).', false, '2026-09-22 16:07:39.241+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('notifications.adminRecipients', '', 'STRING', 'notifications', 'Workshop notification addresses', 'Comma-separated. Recipients of request.submitted, order.placed and quote.expiring (ARCHITECTURE.md section 11). PLACEHOLDER pending the owner: while it is empty the ADMIN_NOTIFICATION_EMAIL variable is used, and with neither set staff notifications are recorded as SKIPPED rather than silently dropped.', false, '2026-09-22 16:07:39.241+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('site.storefrontEnabled', 'true', 'BOOLEAN', 'availability', 'Storefront open', 'When false the public site shows a "we will be back" page instead of the shop. /admin is unaffected, and staff still see the real site with a banner so the owner can check their own shop while it is closed. Defaults to open: an absent row must never read as a closed shop.', false, '2026-09-22 16:07:39.243+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('accounts.emailVerificationRequired', 'true', 'BOOLEAN', 'accounts', 'Require e-mail verification', 'When false every signed-in customer is treated as verified, which unblocks quote acceptance for a shop with no mail provider configured. Defaults to true: an absent row must never quietly switch a security control off.', false, '2026-09-22 16:07:39.244+01', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.settings (key, value, type, "group", label, description, is_secret, updated_at, updated_by_user_id) VALUES ('features.wishlist', 'false', 'BOOLEAN', 'features', 'Wishlist enabled', 'V1.5 feature flag.', false, '2026-09-22 16:07:39.244+01', NULL) ON CONFLICT DO NOTHING;


ALTER TABLE public.settings ENABLE TRIGGER ALL;

